<script setup lang="ts">
import type { Settings } from '../rules/state'
import { MONSTERS } from '../rules/monsters'
import { kinName } from '../dm/campaign'
const p = defineProps<{ set: Settings; ai?: boolean }>(); const S = p.set
const F = ['goblin', 'orc', 'kobold', 'gnoll', 'bandit', 'cult', 'undead', 'fiend', 'dragon', 'giant', 'construct', 'elemental', 'ooze', 'vermin', 'beast', 'plant', 'frost', 'desert', 'drow', 'knight'].filter(f => MONSTERS.some(m => m.fams.includes(f))); const tog = (f: string) => { const i = S.fams.indexOf(f); i >= 0 ? S.fams.splice(i, 1) : S.fams.push(f) }; const cap = (s: string) => s[0].toUpperCase() + s.slice(1)
const D: [Settings['difficulty'], string][] = [['story', 'Story'], ['easy', 'Easy'], ['normal', 'Normal'], ['hard', 'Hard'], ['deadly', 'Deadly']]
</script>
<template><div class="pf"><div><span class="cap">Difficulty</span><div class="chips"><button v-for="d in D" :key="d[0]" class="chip s" :class="{ on: S.difficulty === d[0] }" @click="S.difficulty = d[0]">{{ d[1] }}</button></div><label class="lab">Heroes’ level: {{ S.level }}</label><input v-model.number="S.level" type="range" min="1" max="20" aria-label="Level"><label class="lab">Party size it is built for: {{ S.party }}</label><input v-model.number="S.party" type="range" min="1" max="8" aria-label="Party size"><label class="lab">Rooms with creatures: {{ Math.round(S.density * 100) }}%</label><input v-model.number="S.density" type="range" min="0" max="1" step=".05" aria-label="Density"><label class="lab">{{ S.bossEvery ? `A boss every ${S.bossEvery} rooms` : 'No bosses' }}</label><input v-model.number="S.bossEvery" type="range" min="0" max="25" aria-label="Boss every"><label class="lab">Treasure: {{ ['none', 'scarce', 'poor', 'fair', 'fair', 'rich', 'rich', 'lavish', 'lavish'][Math.round(S.treasure * 4)] }}</label><input v-model.number="S.treasure" type="range" min="0" max="2" step=".25" aria-label="Treasure"></div>
  <div><span class="cap">What keeps the place</span><div class="chips"><button class="chip s" :class="{ on: !S.fams.length }" @click="S.fams.splice(0)">Whatever suits it</button><button v-for="f in F" :key="f" class="chip s" :class="{ on: S.fams.includes(f) }" @click="tog(f)">{{ cap(kinName(f)) }}</button></div><span class="cap">Also</span><button class="opt" :class="{ on: S.autoPopulate }" @click="S.autoPopulate = !S.autoPopulate"><i class="tick" /><span>New rooms get creatures by themselves</span></button><button class="opt" :class="{ on: S.traps }" @click="S.traps = !S.traps"><i class="tick" /><span>Traps</span></button><button class="opt" :class="{ on: S.locks }" @click="S.locks = !S.locks"><i class="tick" /><span>Locked doors and chests</span></button><button class="opt" :class="{ on: S.folk }" @click="S.folk = !S.folk"><i class="tick" /><span>Townsfolk, shops and prisoners</span></button><template v-if="ai"><button class="opt" :class="{ on: S.endless }" @click="S.endless = !S.endless"><i class="tick" /><span>The map grows when you reach its edge</span></button><button class="opt" :class="{ on: S.wander }" @click="S.wander = !S.wander"><i class="tick" /><span>Wandering creatures</span></button><button class="opt" :class="{ on: S.askDice }" @click="S.askDice = !S.askDice"><i class="tick" /><span>Players throw their own dice</span></button><button class="opt" :class="{ on: S.deathRule === 'heroic' }" @click="S.deathRule = S.deathRule === 'heroic' ? 'saves' : 'heroic'"><i class="tick" /><span>Heroes who fall only sleep until the fight ends</span></button></template></div></div></template>
<style scoped>.pf{display:grid;grid-template-columns:1fr 1fr;gap:8px 40px;margin-top:8px}@media(max-width:700px){.pf{grid-template-columns:1fr}}</style>
